import json, hashlib, datetime
from collections import Counter, defaultdict

def norm(v):
    if v is None: return datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
    if isinstance(v,int): return datetime.datetime.fromtimestamp(v/1000,datetime.timezone.utc)
    d=datetime.datetime.fromisoformat(v.replace('Z','+00:00'))
    return d if d.tzinfo else d.replace(tzinfo=datetime.timezone(datetime.timedelta(hours=8)))

def fld(o,k):
    d=o.get('data')
    return d.get(k) if isinstance(d,dict) else None

events=[]
for i,line in enumerate(open('/home/k/dev/me/onec-mle26/data/feed.jsonl',encoding='utf-8'),1):
    try: o=json.loads(line)
    except Exception: continue
    if not isinstance(o,dict): continue
    events.append((i,o,hashlib.sha256(line.rstrip('\n').encode()).hexdigest()))

print("=== data field types across all dict events ===")
print(dict(Counter(type(o.get('data')).__name__ for _,o,_ in events)))
print("\n=== non-dict data events ===")
for i,o,_ in events:
    if not isinstance(o.get('data'),dict) and o.get('data') is not None:
        print(i, json.dumps(o,ensure_ascii=False)[:260])
print("\n=== data:null events (with reg) ===")
for i,o,_ in events:
    if o.get('data') is None: print(i, o.get('type'), o.get('registrationNumber'), o.get('updatedAt'))

# latest-wins per reg, include struck-off
best={}
for i,o,mid in events:
    reg=o.get('registrationNumber')
    if not reg: continue
    t=norm(o.get('updatedAt'))
    if reg not in best or (t,mid)>(best[reg][0],best[reg][1]): best[reg]=(t,mid,o,i)
print("\n=== final rows summary ===")
print('total reg keys:',len(best))
print('final type:',dict(Counter(o.get('type') for _,_,o,_ in best.values())))

# natureOfBusiness value types
print("\n=== natureOfBusiness value types (final upserts) ===")
print(dict(Counter(type(fld(o,'natureOfBusiness')).__name__ for _,_,o,_ in best.values() if o.get('type')=='company-upserted')))

no_desc=[(reg,o,i) for reg,(t,mid,o,i) in best.items() if o.get('type')=='company-upserted' and not (isinstance(fld(o,'natureOfBusiness'),str) and fld(o,'natureOfBusiness').strip())]
print("\n=== final upserts with NO usable description:",len(no_desc))
print('  of those, active/struck-off as final:',dict(Counter(o.get('type') for _,o,_ in no_desc)))

# surrogate availability
empty_surrogate=[]
for reg,o,i in no_desc:
    parts=[fld(o,k) for k in ('industry','companyName','state')]
    usable=[p.strip() for p in parts if isinstance(p,str) and p.strip()]
    if not usable: empty_surrogate.append((reg,o,i,parts))
print("\n=== no-desc with EMPTY surrogate (no name/industry/state):",len(empty_surrogate))
for reg,o,i,parts in empty_surrogate:
    print('  reg',reg,'line',i,'data=',json.dumps(o.get('data'),ensure_ascii=False)[:200])

# what do those empty-surrogate companies look like across ALL their events
print("\n=== all events for empty-surrogate regs ===")
for reg,o,i,parts in empty_surrogate:
    evs=[(j,x) for j,x,_ in events if x.get('registrationNumber')==reg]
    print(' ',reg,'events:',len(evs))
    for j,x in evs:
        print('    ',j,x.get('type'),x.get('updatedAt'),json.dumps(x.get('data'),ensure_ascii=False)[:160])

# name-only events (14) - do they have reg?
print("\n=== events whose data has ONLY companyName ===")
cnt=0
for i,o,_ in events:
    d=o.get('data')
    if isinstance(d,dict) and set(d.keys())=={'companyName'}:
        cnt+=1
        if cnt<=20: print(' ',i,'reg=',o.get('registrationNumber'),'type=',o.get('type'),'name=',repr(d.get('companyName')),'updatedAt=',o.get('updatedAt'))
print(' total:',cnt)

